import type { CSSProperties } from 'react'

// EASEL-DIVERGENCE(easel-standalone-client L1): official Easel-dsh badge
// (design-assets/app-icons/easel-icon.png) inlined as a data URI so the client
// bundle stays self-contained. The white rounded base keeps the mark legible
// on light and dark surfaces alike.
const BADGE_SRC = 'data:image/png;base64,'

export function EaselLogo({ size = 24, style }: { size?: number; style?: CSSProperties }) {
  return (
    <img
      src={BADGE_SRC}
      width={size}
      height={size}
      alt=""
      draggable={false}
      style={{ borderRadius: Math.max(2, size * 0.18), objectFit: 'contain', ...style }}
    />
  )
}

// EASEL-DIVERGENCE(easel-brand-mark): the blank-session hero shows the same
// artwork as the app icon without its white rounded tile, so the mark reads as
// a mark rather than a tile beside the greeting. Derived from
// apps/desktop-tauri/src-tauri/icons/official-512.png by flood-filling the tile
// white from the border — the white the glyph encloses (the canvas) survives,
// everything outside it turns transparent — then centering the glyph in a
// square canvas (the artwork is taller than it is wide).
const MARK_SRC = 'data:image/png;base64,'

/**
 * Render the Easel artwork alone, without the app-icon tile behind it.
 * @param props.size - square edge in CSS pixels.
 * @param props.className - class applied to the image element.
 * @returns the transparent-background mark image.
 */
export function EaselMark({ size = 34, className }: { size?: number; className?: string | undefined }) {
  return (
    <img src={MARK_SRC} width={size} height={size} alt="" draggable={false} className={className} />
  )
}
